files = subprocess.check_output("grep -rln 'netif_napi_add' drivers/net drivers/staging net --include=*.c",shell=True,text=True).split()
rows=[]
for f in files:
    src=open(f,errors='ignore').read().splitlines()
    text="\n".join(src)
    cbs=set()
    for m in re.finditer(r'netif_napi_add(?:_weight)?\s*\(([^;]*)\)',text,re.S):
        args=[a.strip() for a in m.group(1).replace("\n"," ").split(",")]
        for a in args[2:4]:
            if re.match(r'^[A-Za-z_][A-Za-z_0-9]*$',a) and a not in ("NAPI_POLL_WEIGHT","NAPI_WEIGHT","NAPI_BUDGET"):
                cbs.add(a)
    for cb in cbs:
        m=re.search(r'(?:static\s+)?(?:int|void)\s+'+cb+r'\s*\(',text)
        if not m: continue
        start=text[:m.start()].count("\n")
        b=text.index("{",m.end()); depth=0
        for j in range(b,len(text)):
            if text[j]=="{":depth+=1
            elif text[j]=="}":
                depth-=1
                if depth==0:break
        body=text[b:j]
        plain=set(x.strip() for x in re.findall(r'spin_lock\(\s*&?([^)]+)\)',body))
        if plain:
            rows.append((f,start+1,sorted(plain)))
for f,l,locks in rows: print(f"{f}:{l}: {', '.join(locks)}")
EOF

